package com.jinloes.practice;
import java.util.*;
public class Solution { private final Map<String,TreeMap<Integer,Integer>> byName=new TreeMap<>(); public Solution(){} public void recordTweet(String name,int time){ byName.computeIfAbsent(name,k->new TreeMap<>()).merge(time,1,Integer::sum); } public List<Integer> getTweetCountsPerFrequency(String freq,String name,int start,int end){ int size=switch(freq){case "minute"->60; case "hour"->3600; case "day"->86400; default->throw new IllegalArgumentException();}; int buckets=(end-start)/size+1; List<Integer> ans=new ArrayList<>(); for(int i=0;i<buckets;i++) ans.add(0); TreeMap<Integer,Integer> m=byName.get(name); if(m==null) return ans; for(Map.Entry<Integer,Integer> e:m.subMap(start,true,end,true).entrySet()){ int b=(e.getKey()-start)/size; ans.set(b,ans.get(b)+e.getValue()); } return ans; } }
